        $this->assertSchema($db,$prefix);\IssuerTransaction::assertOwned($db,$prefix,$this->tables());$this->auth($issuer,$actor,true);$request=$this->requestRow($issuer,$this->request);[$source,$account]=$this->assertIntentCurrent($issuer,$actor,$request,false);if($source['payment_id']===null)throw new \DomainException('company_asaas_full_refund_native_receipt_required');
