        $store=new \CompanyAsaasRefundPostings($db,$prefix);$original=$store->originalForStaffInOwned($issuer,$actor,$source['invoice_id'],$source['payment_id'],$this->request,$this->observation);$dto=\CompanyAsaasRefundData::declare($original,$this->declaration,gmdate('Y-m-d'));$old=$store->capturedInOwned($issuer,$actor,$source['invoice_id'],$source['payment_id']);if($old){if(!hash_equals($old->fingerprint(),$dto->fingerprint()))throw new \DomainException('company_asaas_full_refund_conflict');}
